import type { Vec2 } from "../math/vec2";
import type { Body } from "../dynamics/body";
import type { AABB } from "../world/aabb";
import type { Manifold } from "../narrowphase/manifold";
import type { DrawPrim } from "../trace/trace";
import { palette, resolveColor, type Palette } from "./colors";
import { fitCanvas, viewSize, visibleWorld, worldToScreen, type View } from "./view";

const FONT = "12px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";

/** Clears the canvas and draws a 1 m grid with the axes. */
export function clear(view: View, pal: Palette = palette()): void {
  fitCanvas(view);
  const { ctx } = view;
  const { width, height } = viewSize(view);
  ctx.fillStyle = pal.background;
  ctx.fillRect(0, 0, width, height);

  const { min, max } = visibleWorld(view);
  const step = view.pixelsPerMetre < 12 ? 10 : 1;
  ctx.lineWidth = 1;
  for (let x = Math.ceil(min.x / step) * step; x <= max.x; x += step) {
    const s = worldToScreen(view, { x, y: 0 });
    ctx.strokeStyle = x === 0 ? pal.axis : pal.grid;
    line(ctx, Math.round(s.x) + 0.5, 0, Math.round(s.x) + 0.5, height);
  }
  for (let y = Math.ceil(min.y / step) * step; y <= max.y; y += step) {
    const s = worldToScreen(view, { x: 0, y });
    ctx.strokeStyle = y === 0 ? pal.axis : pal.grid;
    line(ctx, 0, Math.round(s.y) + 0.5, width, Math.round(s.y) + 0.5);
  }
}

function line(ctx: CanvasRenderingContext2D, x0: number, y0: number, x1: number, y1: number) {
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.stroke();
}

function rotate(v: Vec2, angle: number): Vec2 {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return { x: c * v.x - s * v.y, y: s * v.x + c * v.y };
}

/** Draws one body. Circles show a radius line so you can see them spin. */
export function drawBody(view: View, body: Body, color?: string, pal: Palette = palette()): void {
  const { ctx } = view;
  const isStatic = body.invMass === 0;
  ctx.strokeStyle = color ?? (isStatic ? pal.static : pal.dynamic);
  ctx.lineWidth = 1.5;
  const shape = body.shape;

  if (shape.kind === "circle") {
    const c = worldToScreen(view, body.position);
    const r = shape.radius * view.pixelsPerMetre;
    ctx.beginPath();
    ctx.arc(c.x, c.y, r, 0, Math.PI * 2);
    ctx.stroke();
    const edge = worldToScreen(view, {
      x: body.position.x + Math.cos(body.angle) * shape.radius,
      y: body.position.y + Math.sin(body.angle) * shape.radius,
    });
    line(ctx, c.x, c.y, edge.x, edge.y);
  } else if (shape.kind === "box") {
    const { halfWidth: hw, halfHeight: hh } = shape;
    const corners = [
      { x: -hw, y: -hh },
      { x: hw, y: -hh },
      { x: hw, y: hh },
      { x: -hw, y: hh },
    ].map((v) => {
      const r = rotate(v, body.angle);
      return { x: body.position.x + r.x, y: body.position.y + r.y };
    });
    polygon(view, corners);
    ctx.stroke();
  } else {
    // A plane: its surface line across the visible area, hatched on the solid side.
    const n = shape.normal;
    const t = { x: -n.y, y: n.x };
    const base = { x: n.x * shape.offset, y: n.y * shape.offset };
    const { min, max } = visibleWorld(view);
    const reach = Math.hypot(max.x - min.x, max.y - min.y) + Math.hypot(base.x, base.y);
    const a = worldToScreen(view, { x: base.x - t.x * reach, y: base.y - t.y * reach });
    const b = worldToScreen(view, { x: base.x + t.x * reach, y: base.y + t.y * reach });
    line(ctx, a.x, a.y, b.x, b.y);
    ctx.save();
    ctx.globalAlpha = 0.35;
    ctx.lineWidth = 1;
    const spacing = 12 / view.pixelsPerMetre;
    const depth = 10 / view.pixelsPerMetre;
    const count = Math.ceil((2 * reach) / spacing);
    for (let i = 0; i < count; i++) {
      const d = -reach + i * spacing;
      const p = { x: base.x + t.x * d, y: base.y + t.y * d };
      const s0 = worldToScreen(view, p);
      const s1 = worldToScreen(view, {
        x: p.x - n.x * depth - t.x * depth,
        y: p.y - n.y * depth - t.y * depth,
      });
      line(ctx, s0.x, s0.y, s1.x, s1.y);
    }
    ctx.restore();
  }
}

function polygon(view: View, pts: Vec2[]): void {
  const { ctx } = view;
  ctx.beginPath();
  pts.forEach((p, i) => {
    const s = worldToScreen(view, p);
    if (i === 0) ctx.moveTo(s.x, s.y);
    else ctx.lineTo(s.x, s.y);
  });
  ctx.closePath();
}

/** Draws an AABB as a dashed rectangle. Infinite AABBs (planes) are skipped. */
export function drawAABB(view: View, aabb: AABB, color?: string, pal: Palette = palette()): void {
  const values = [aabb.min.x, aabb.min.y, aabb.max.x, aabb.max.y];
  if (!values.every(Number.isFinite)) return;
  const { ctx } = view;
  const a = worldToScreen(view, aabb.min);
  const b = worldToScreen(view, aabb.max);
  ctx.save();
  ctx.setLineDash([4, 3]);
  ctx.strokeStyle = color ?? pal.muted;
  ctx.lineWidth = 1;
  ctx.strokeRect(a.x, b.y, b.x - a.x, a.y - b.y);
  ctx.restore();
}

/** Draws a manifold: each contact point, its depth, and the normal from A to B. */
export function drawManifold(view: View, m: Manifold, pal: Palette = palette()): void {
  for (const cp of m.points) {
    drawPrim(view, { kind: "point", p: cp.point, color: "contact" }, pal);
    const tip = {
      x: cp.point.x + m.normal.x * Math.max(cp.depth, 0.3),
      y: cp.point.y + m.normal.y * Math.max(cp.depth, 0.3),
    };
    drawPrim(view, { kind: "arrow", from: cp.point, to: tip, color: "normal" }, pal);
  }
}

/** Draws one trace primitive. */
export function drawPrim(view: View, prim: DrawPrim, pal: Palette = palette()): void {
  const { ctx } = view;
  const color = resolveColor(prim.color, pal);
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = 2;
  ctx.font = FONT;
  let labelAt: Vec2 | null = null;
  let label: string | undefined;

  switch (prim.kind) {
    case "point": {
      const s = worldToScreen(view, prim.p);
      ctx.beginPath();
      ctx.arc(s.x, s.y, 4, 0, Math.PI * 2);
      ctx.fill();
      labelAt = s;
      label = prim.label;
      break;
    }
    case "segment": {
      const a = worldToScreen(view, prim.a);
      const b = worldToScreen(view, prim.b);
      line(ctx, a.x, a.y, b.x, b.y);
      labelAt = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
      label = prim.label;
      break;
    }
    case "arrow": {
      const a = worldToScreen(view, prim.from);
      const b = worldToScreen(view, prim.to);
      line(ctx, a.x, a.y, b.x, b.y);
      const ang = Math.atan2(b.y - a.y, b.x - a.x);
      const head = 9;
      ctx.beginPath();
      ctx.moveTo(b.x, b.y);
      ctx.lineTo(b.x - head * Math.cos(ang - 0.4), b.y - head * Math.sin(ang - 0.4));
      ctx.lineTo(b.x - head * Math.cos(ang + 0.4), b.y - head * Math.sin(ang + 0.4));
      ctx.closePath();
      ctx.fill();
      // Label at the midpoint, so arrows that share a tip keep readable labels.
      labelAt = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
      label = prim.label;
      break;
    }
    case "circle": {
      const c = worldToScreen(view, prim.c);
      ctx.beginPath();
      ctx.arc(c.x, c.y, prim.r * view.pixelsPerMetre, 0, Math.PI * 2);
      ctx.stroke();
      break;
    }
    case "polygon": {
      polygon(view, prim.pts);
      ctx.save();
      ctx.globalAlpha = 0.12;
      ctx.fill();
      ctx.restore();
      ctx.stroke();
      break;
    }
    case "text": {
      labelAt = worldToScreen(view, prim.p);
      label = prim.text;
      break;
    }
  }

  if (label && labelAt) {
    ctx.fillText(label, labelAt.x + 6, labelAt.y - 6);
  }
}

/** Draws every primitive of a trace frame. */
export function drawPrims(view: View, prims: readonly DrawPrim[], pal: Palette = palette()): void {
  for (const p of prims) drawPrim(view, p, pal);
}

/** Draws a message in the top-left corner, for example a TODO error. */
export function drawMessage(view: View, text: string, pal: Palette = palette()): void {
  const { ctx } = view;
  ctx.font = FONT;
  ctx.fillStyle = pal.ink;
  text.split("\n").forEach((l, i) => ctx.fillText(l, 12, 20 + i * 16));
}
